package com.kitehybrid.synthetic;

import java.time.Duration;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.testcontainers.containers.GenericContainer;
import org.testcontainers.containers.startupcheck.OneShotStartupCheckStrategy;
import com.github.dockerjava.api.model.Capability;
import static org.junit.jupiter.api.Assertions.*;

/** Kernel-policy probes in an owned cached image. This is NOT the Java owner deployment. */
class ContainmentIT {
    static GenericContainer<?> sandbox(long pids) {
        return new GenericContainer<>("postgres:17.6").withImagePullPolicy(ignored->false)
            .withNetworkMode("none").withCreateContainerCmdModifier(cmd->{
                cmd.withUser("65534:65534").withEntrypoint("/bin/sleep");
                cmd.getHostConfig().withReadonlyRootfs(true).withCapDrop(Capability.ALL)
                    .withSecurityOpts(List.of("no-new-privileges:true")).withMemory(67108864L)
                    .withNanoCPUs(500000000L).withPidsLimit(pids)
                    .withTmpFs(Map.of("/scratch","rw,noexec,nosuid,nodev,size=1m,mode=1777",
                        "/var/lib/postgresql/data","ro,noexec,nosuid,nodev,size=1m"));
            }).withCommand("120");
    }
    static void inspect(GenericContainer<?> container,long pids) {
        var info=container.getDockerClient().inspectContainerCmd(container.getContainerId()).exec();var host=info.getHostConfig();
        assertEquals("none",host.getNetworkMode());assertEquals(Boolean.TRUE,host.getReadonlyRootfs());
        assertEquals("65534:65534",info.getConfig().getUser());assertEquals(pids,host.getPidsLimit());
        assertEquals(67108864L,host.getMemory());assertEquals(500000000L,host.getNanoCPUs());
        assertTrue(host.getSecurityOpts().contains("no-new-privileges:true"));assertTrue(Arrays.asList(host.getCapDrop()).contains(Capability.ALL));
        assertTrue(host.getBinds()==null||host.getBinds().length==0);
        if(info.getMounts()!=null)for(var mount:info.getMounts()) {
            assertTrue(mount.getSource()==null||mount.getSource().isBlank());
            assertTrue(mount.getName()==null||mount.getName().isBlank());
            assertTrue(Set.of("/scratch","/var/lib/postgresql/data").contains(mount.getDestination().getPath()));
        }
    }
    @Test void readOnlyUnprivilegedNetworkNoneKernelPolicyIsEnforced() throws Exception {
        try(var container=sandbox(16)) {
            container.start();inspect(container,16);
            var result=container.execInContainer("/bin/bash","-c","""
                set -eu
                [ "$UID" != 0 ]
                caps=missing; priv=missing
                while read -r name value rest; do
                  case "$name" in CapEff:) caps="$value";; NoNewPrivs:) priv="$value";; esac
                done < /proc/self/status
                [ "$caps" = 0000000000000000 ]; [ "$priv" = 1 ]
                if (printf x > /synthetic-root-write) 2>/dev/null; then exit 31; fi
                printf SYNTHETIC_ONLY > /scratch/allowed
                [ -r /scratch/allowed ]
                [ ! -e /host ]; [ ! -e /mnt/c ]; [ ! -e /var/run/docker.sock ]
                [ -z "${JAVA_TOOL_OPTIONS+x}" ]; [ -z "${SYNTHETIC_HOST_SECRET+x}" ]
                while read -r iface rest; do [ "$iface" = Iface ] || exit 32; done < /proc/net/route
                if timeout 2 bash -c 'exec 3<>/dev/tcp/192.0.2.1/9' >/dev/null 2>&1; then exit 33; fi
                if timeout 2 getent ahostsv4 synthetic-fixture.invalid >/dev/null 2>&1; then exit 34; fi
                printf SYNTHETIC_KERNEL_POLICY_PASS
                """);
            assertEquals(0,result.getExitCode(),"SYNTHETIC_KERNEL_POLICY_FAILED");
            assertEquals("SYNTHETIC_KERNEL_POLICY_PASS",result.getStdout());assertEquals("",result.getStderr());
            assertEquals("",container.getLogs());
        }
    }
    @Test void pidCgroupDeniesChildProcessCreation() throws Exception {
        try(var container=sandbox(1).withCreateContainerCmdModifier(cmd->cmd.withEntrypoint("/bin/bash"))
            .withCommand("-c","/bin/true; code=$?; if [ \"$code\" = 0 ]; then exit 35; fi; printf SYNTHETIC_FORK_DENIED")
            .withStartupCheckStrategy(new OneShotStartupCheckStrategy(){
                @Override public StartupStatus checkStartupState(com.github.dockerjava.api.DockerClient docker,String id) {
                    var state=getCurrentState(docker,id);
                    return "exited".equals(state.getStatus())?StartupStatus.SUCCESSFUL:StartupStatus.NOT_YET_KNOWN;
                }
            }.withTimeout(Duration.ofSeconds(25)))) {
            container.start();inspect(container,1);
            var state=container.getDockerClient().inspectContainerCmd(container.getContainerId()).exec().getState();
            assertFalse(Boolean.TRUE.equals(state.getOOMKilled()));
            assertNotEquals(0L,state.getExitCodeLong());
            String logs=container.getLogs();assertTrue(logs.contains("fork"));assertTrue(logs.contains("Resource temporarily unavailable"));
            assertFalse(logs.contains("SYNTHETIC_HOST_SECRET"));
        }
    }
}

package com.kitehybrid.synthetic;

import java.sql.*;
import java.util.UUID;
import org.testcontainers.containers.PostgreSQLContainer;

/** Test-only adapter. No JDBC, schema DDL or connection configuration in runtime JAR. */
final class DisposableLedger implements SyntheticOwner.Ledger {
    enum Fault { NONE, PARTIAL_JOURNAL, BEFORE_RESERVATION, DURING_RESERVATION,
        AFTER_RESERVATION_BEFORE_ACK, BEFORE_COMMIT, AFTER_COMMIT_BEFORE_ACK }
    private final String url, marker;
    private final Fault fault;
    private final java.util.function.Consumer<String> observer;
    final AttemptJournal journal;
    static PostgreSQLContainer<?> container() {
        return new PostgreSQLContainer<>("postgres:17.6").withDatabaseName("synthetic_owner_only")
                .withImagePullPolicy(ignored -> false)
                .withUsername("synthetic_fixture").withPassword("synthetic_fixture")
                .withCommand("postgres", "-c", "fsync=on", "-c", "full_page_writes=on", "-c", "synchronous_commit=on");
    }
    static DisposableLedger initialize(PostgreSQLContainer<?> container) throws Exception {
        String marker = UUID.randomUUID().toString();
        var ledger = new DisposableLedger(container.getMappedPort(5432), marker, Fault.NONE);
        ledger.journal.initialize();
        try (var c = ledger.open(); var s = c.createStatement()) {
            s.execute("CREATE TABLE fixture_identity (id text PRIMARY KEY)");
            try (var p = c.prepareStatement("INSERT INTO fixture_identity VALUES (?)")) { p.setString(1, marker); p.executeUpdate(); }
            s.execute("CREATE TABLE attempts (id uuid PRIMARY KEY, digest text NOT NULL, halt_digest text NOT NULL, state text NOT NULL CHECK(state IN ('RESERVED','CONSUMED')), outcome text CHECK(outcome IN ('SYNTHETIC_READ_SUCCEEDED','SYNTHETIC_READ_DENIED','SYNTHETIC_READ_OUTCOME_UNKNOWN','PROTOTYPE_PRECONDITION_FAILED')), CHECK(outcome IS NULL OR state='CONSUMED'))");
        }
        return ledger;
    }
    DisposableLedger(int port, String marker, Fault fault) {
        this(port, marker, fault, ignored -> {});
    }
    DisposableLedger(int port, String marker, Fault fault, java.util.function.Consumer<String> observer) {
        if (port < 1 || port > 65535 || marker == null) throw SyntheticOwner.denied();
        UUID.fromString(marker);
        url = "jdbc:postgresql://127.0.0.1:" + port + "/synthetic_owner_only?connectTimeout=2&socketTimeout=3";
        this.marker = marker; this.fault = fault;
        this.observer = observer;
        journal = new AttemptJournal(marker, observer);
    }
    String marker() { return marker; }
    private Connection open() throws SQLException { return DriverManager.getConnection(url, "synthetic_fixture", "synthetic_fixture"); }
    private void validate(Connection c) throws SQLException {
        try (var s = c.createStatement()) {
            s.setQueryTimeout(3);
            for (String setting : new String[]{"fsync", "full_page_writes", "synchronous_commit"}) {
                try (var r = s.executeQuery("SHOW " + setting)) { if (!r.next() || !"on".equals(r.getString(1))) throw new SQLException(); }
            }
            try (var r = s.executeQuery("SELECT id FROM fixture_identity")) {
                if (!r.next() || !marker.equals(r.getString(1)) || r.next()) throw new SQLException();
            }
        }
    }
    @Override public boolean consume(SyntheticOwner.Request request) {
        return consume(request, "0".repeat(64)); // Ledger-only fixture, never owner authorization.
    }
    @Override public boolean consume(SyntheticOwner.Request request, String haltDigest) {
        try {
            if (haltDigest == null || !haltDigest.matches("[0-9a-f]{64}")) return false;
            if (!journal.retire(request.id(), request.fingerprint() + ":" + haltDigest, fault == Fault.PARTIAL_JOURNAL)) return false;
        } catch (Exception ignored) { return false; }
        if (fault == Fault.BEFORE_RESERVATION) return false;
        // Unique reservation has its own durable commit. Even a rolled-back consume is spent.
        try (var c = open()) {
            validate(c);
            c.setAutoCommit(false);
            try (var p = c.prepareStatement("INSERT INTO attempts VALUES (?,?,?,'RESERVED',NULL) ON CONFLICT DO NOTHING")) {
                p.setQueryTimeout(3); p.setObject(1, request.id()); p.setString(2, request.fingerprint()); p.setString(3, haltDigest);
                if (p.executeUpdate() != 1) return false;
            }
            if (fault == Fault.DURING_RESERVATION) { c.rollback(); return false; }
            observer.accept("BEFORE_RESERVATION_COMMIT");
            c.commit();
            observer.accept("AFTER_RESERVATION_COMMIT");
            if (fault == Fault.AFTER_RESERVATION_BEFORE_ACK) return false;
            try (var p = c.prepareStatement("UPDATE attempts SET state='CONSUMED' WHERE id=? AND digest=? AND halt_digest=? AND state='RESERVED'")) {
                p.setQueryTimeout(3); p.setObject(1, request.id()); p.setString(2, request.fingerprint()); p.setString(3, haltDigest);
                if (p.executeUpdate() != 1) { c.rollback(); return false; }
            }
            if (fault == Fault.BEFORE_COMMIT) { c.rollback(); return false; }
            observer.accept("BEFORE_CONSUMPTION_COMMIT");
            c.commit();
            observer.accept("AFTER_CONSUMPTION_COMMIT");
            return fault != Fault.AFTER_COMMIT_BEFORE_ACK;
        } catch (Exception ignored) { return false; } // Unknown reservation/commit: no grant, never retry.
    }
    @Override public void terminal(UUID id, SyntheticOwner.Outcome outcome) {
        try (var c = open()) {
            validate(c);
            try (var p = c.prepareStatement("UPDATE attempts SET outcome=? WHERE id=? AND state='CONSUMED' AND outcome IS NULL")) {
                p.setQueryTimeout(3); p.setString(1, outcome.name()); p.setObject(2, id);
                if (p.executeUpdate() != 1) throw SyntheticOwner.denied();
            }
        } catch (Exception ignored) { throw SyntheticOwner.denied(); }
    }
    String state(UUID id) throws Exception {
        try (var c = open()) {
            validate(c);
            try (var p = c.prepareStatement("SELECT state FROM attempts WHERE id=?")) {
                p.setObject(1,id); try (var r=p.executeQuery()) { return r.next()?r.getString(1):"ABSENT"; }
            }
        }
    }
    String digest(UUID id) throws Exception {
        try(var c=open();var p=c.prepareStatement("SELECT digest FROM attempts WHERE id=?")) {
            p.setObject(1,id);try(var r=p.executeQuery()){return r.next()?r.getString(1):"ABSENT";}
        }
    }
    void verifyDurabilitySettings() throws Exception { try (var c = open()) { validate(c); } }
    String haltDigest(UUID id) throws Exception {
        try (var c=open(); var p=c.prepareStatement("SELECT halt_digest FROM attempts WHERE id=?")) {
            p.setObject(1,id); try (var r=p.executeQuery()) { return r.next()?r.getString(1):"ABSENT"; }
        }
    }
}

